/**
 * Build by percent (link PR 3): the Build stage read from the jobs' percent
 * complete. Built per week is each job's change in percent times its contract,
 * walked in date order over the hand-set percents and the field reports. Sold
 * per week is the contract on jobs created in the window. The pile is the
 * contract left on open jobs; a job with no percent is read as half done and
 * drawn grey. Pure: the loader beside it (`loadBuildPace.ts`) does the reads.
 */
import { payWeekContaining } from '../payWeekAnchor.ts'
import type { BuildStageInput } from './stageFlow.ts'

export type PctPoint = { jobId: string; atYmd: string; pct: number; source: 'hand' | 'report' }

export type BuildJob = {
  id: string
  /** "J949 · Dominguez- Run camera": the number and the name, the way the dashboard's percent modal shows a job. */
  label: string
  /** The job's display number, HCP first then Click; '' when it has neither. */
  hcpNumber: string
  jobName: string
  revenueUsd: number | null
  pctComplete: number | null
  status: string
  createdYmd: string | null
}

export type BuildPaceInput = {
  windowStart: string
  todayYmd: string
  /** Open jobs: waiting to start or working, billing-only and the office job left out. */
  openJobs: BuildJob[]
  /** Jobs touched by a percent point in the window, open or not, with their contract. */
  jobsByPoint: Map<string, BuildJob>
  /** Percent points from before the window start (the baseline) through today. */
  points: PctPoint[]
  /** Jobs created in the window, with their contract. */
  createdInWindow: Array<{ id: string; revenueUsd: number | null }>
}

export type BuildPace = {
  builtByWeek: Map<string, number>
  builtUsd: number
  builtPerWeekUsd: number
  soldUsd: number
  soldJobs: number
  soldPerWeekUsd: number
  pile: { knownUsd: number; knownJobs: number; guessUsd: number; guessJobs: number; noPriceJobs: number; openJobs: number }
  weeks: number
  stageInput: BuildStageInput
}

/** The leading number of a report's "How complete is the job?" answer, clamped to 0–100; null when it has none. */
export function parseReportPct(raw: string | null | undefined): number | null {
  if (raw == null) return null
  const m = String(raw).trim().match(/^[+-]?\d+/)
  if (!m) return null
  const n = Number(m[0])
  if (!Number.isFinite(n)) return null
  return Math.max(0, Math.min(100, n))
}

const weeksIn = (windowStart: string, todayYmd: string): number => Math.max(1, (Date.parse(`${todayYmd}T00:00:00Z`) - Date.parse(`${windowStart}T00:00:00Z`)) / (7 * 86_400_000))

export function buildBuildPace(input: BuildPaceInput): BuildPace {
  const weeks = weeksIn(input.windowStart, input.todayYmd)
  const builtByWeek = new Map<string, number>()

  // Walk each job's points in date order; a hand-set and a report on the same day at the same percent are one point.
  const byJob = new Map<string, PctPoint[]>()
  for (const p of input.points) {
    const list = byJob.get(p.jobId) ?? []
    if (!list.some((q) => q.atYmd === p.atYmd && q.pct === p.pct)) list.push(p)
    byJob.set(p.jobId, list)
  }
  let builtUsd = 0
  for (const [jobId, list] of byJob) {
    const job = input.jobsByPoint.get(jobId)
    const revenue = job?.revenueUsd ?? 0
    if (!(revenue > 0)) continue
    list.sort((a, b) => (a.atYmd < b.atYmd ? -1 : a.atYmd > b.atYmd ? 1 : a.source === 'report' && b.source === 'hand' ? -1 : 0))
    const before = list.filter((p) => p.atYmd < input.windowStart)
    const inWindow = list.filter((p) => p.atYmd >= input.windowStart && p.atYmd <= input.todayYmd)
    if (inWindow.length === 0) continue
    let current: number
    if (before.length) current = before[before.length - 1]!.pct
    else if (job?.createdYmd && job.createdYmd >= input.windowStart) current = 0
    else current = inWindow[0]!.pct
    for (const p of inWindow) {
      const delta = ((p.pct - current) / 100) * revenue
      if (delta !== 0) {
        const wk = payWeekContaining(p.atYmd).start
        builtByWeek.set(wk, (builtByWeek.get(wk) ?? 0) + delta)
        builtUsd += delta
      }
      current = p.pct
    }
  }

  let soldUsd = 0
  for (const j of input.createdInWindow) soldUsd += j.revenueUsd ?? 0

  let knownUsd = 0
  let knownJobs = 0
  let guessUsd = 0
  let guessJobs = 0
  let noPriceJobs = 0
  for (const j of input.openJobs) {
    if (!(j.revenueUsd != null && j.revenueUsd > 0)) {
      noPriceJobs += 1
      continue
    }
    if (j.pctComplete == null) {
      guessUsd += j.revenueUsd * 0.5
      guessJobs += 1
    } else {
      knownUsd += j.revenueUsd * (1 - Math.max(0, Math.min(100, j.pctComplete)) / 100)
      knownJobs += 1
    }
  }

  const builtPerWeekUsd = builtUsd / weeks
  const soldPerWeekUsd = soldUsd / weeks
  return {
    builtByWeek,
    builtUsd,
    builtPerWeekUsd,
    soldUsd,
    soldJobs: input.createdInWindow.length,
    soldPerWeekUsd,
    pile: { knownUsd, knownJobs, guessUsd, guessJobs, noPriceJobs, openJobs: input.openJobs.length },
    weeks,
    stageInput: { pileUsd: knownUsd, pileCount: knownJobs, inPerWeekUsd: soldPerWeekUsd, outPerWeekUsd: builtPerWeekUsd, knownJobs, guessUsd, guessJobs },
  }
}
